import { useState } from 'react';

import { challengeList }  from './Pointcalc.js'
import filters from './filters.json';

import udcc_logo from './img/udcc_logo.png';
import {States, StatesToNumbers} from "./Pointcalc.js";

function FilterCheckbox({id, checked, text, cat, updateFilter}) {
    return (
        <div>
            <label>
                <input checked={checked} type="checkbox" onChange={(e) => updateFilter(id, e.target.checked, cat, text)}/>
                    {' '}
                    {text}
            </label>
        </div>
    );
}

function Checkbox({id, checked, text, onChange}) {
    return(
        <div className="otherOption">
            <label>
                <input checked={checked} type="checkbox" onChange={(e) => onChange(id)}/>
                {' '}
                {text}
            </label>
        </div>
    )
}

function Searchbar({searchText, updateSearchText}) {
    return (
        <input id="searchbar" type="text" value={searchText} onChange={(e) => updateSearchText(e.target.value)} placeholder="Search..."/>
    )
}

export default function Sidebar({importSelection, exportSelection, updateChallenges, clearSelection, dependencySet, bucketListSet}) {
    const [enabled, setEnabled] = useState(false);

    const [checked, setChecked] = useState([]);

    const [filter, setFilter] = useState(Array.from({length: filters.length}, () => new Set()));

    const [searchText, setSearchText] = useState("");

    function resetCheckboxes() {
        setChecked([]);

        clearFilter();

        dependencySet(false);
        bucketListSet(false);
    }
    
    function clearFilter() {
        var newFilter = Array.from({length: filters.length}, () => new Set());
        var newText = "";

        setFilter(newFilter);
        setSearchText(newText);
        
        filterChallenges(newFilter, newText);
    }

    function updateFilter(state, cat, option) {
        const newFilter = filter.slice();

        if (state) newFilter[cat].add(StatesToNumbers(option));
        else newFilter[cat].delete(StatesToNumbers(option));
        
        filterChallenges(newFilter, searchText);
        setFilter(newFilter);
    }

    function filterChallenges(newFilter, newText) {
        let challenges = challengeList;
        const selection = new Map(JSON.parse(localStorage.getItem("selection")));

        console.log(challenges)
        newFilter.forEach((catFilter, index) => {
            if (index === 3) {
                challenges = catFilter.size === 0 ? challenges : challenges.filter((c) => catFilter.has(selection.get(c.id) ?? States.Incomplete));
            } else {
                challenges = catFilter.size === 0 ? challenges : challenges.filter((c) => catFilter.has(c[slugify(filters[index].name)]));
            }
        })

        challenges = challenges.filter((c) => c.name.toLowerCase().indexOf(newText.toLowerCase()) !== -1);
         
        updateChallenges(challenges);
    }

    function updateCheckbox(id, state, cat, option) {
        var nextChecked = checked.slice();
        nextChecked[id] = !nextChecked[id];
        setChecked(nextChecked);

        updateFilter(state, cat, option);
    }

    function updateSearchText(text) {
        setSearchText(text);

        filterChallenges(filter, text);
    }

    function updateDependencyCheckbox(id) {
        var nextChecked = checked.slice();
        nextChecked[id] = !nextChecked[id];
        setChecked(nextChecked);

        dependencySet(nextChecked[id]);
    }

    function updateBucketListCheckbox(id) {
        var nextChecked = checked.slice();
        nextChecked[id] = !nextChecked[id];
        setChecked(nextChecked);

        bucketListSet(nextChecked[id]);
    }

    async function handleFileUpload(e) {
        try {
            if (e.target.files) {
                const data = await e.target.files[0].text()
                importSelection(data)
            }
        } catch (e) {
            alert("Could not import selection. Make sure the selected file is valid and try again.")
            console.error(e)
        }
    }

    if (enabled) {
        var filterCategories = [];
        var i = 0;
        var id;
        filters.forEach((cat, index) => {
            var filterOptions = [];
            Object.entries(cat.options).forEach((option) => {
                id = i;
                var isChecked = checked[id] === undefined ? false : checked[id];
                filterOptions.push(<FilterCheckbox key={id} id={id} checked={isChecked} text={option[1]} cat={index} updateFilter={updateCheckbox}/>);
                ++i;
            });

            filterCategories.push(<div key={index}><div className="catName">{cat.name}</div><div>{filterOptions}</div></div>);
        });

        var isChecked
        var otherCheckboxes = [];
        
        ++id;
        isChecked = checked[id] === undefined ? false : checked[id];
        otherCheckboxes.push(<Checkbox key={id} id={id} checked={isChecked} text="Autoselect dependencies" onChange={updateDependencyCheckbox} />)

        ++id;
        isChecked = checked[id] === undefined ? false : checked[id];
        otherCheckboxes.push(<Checkbox key={id} id={id} checked={isChecked} text="Bucket list mode" onChange={updateBucketListCheckbox} />)

        return (
            <div id="sidenav">
                <ul>
                    <li id="filter">
                        <button onClick={() => setEnabled(false)} id="closebutton"><h1>X</h1></button>
                        <div id="bottomtext">
                            <img src={udcc_logo} alt="determination"></img>
                            <p>Maintained by <a href="https://discord.gg/WVFcWXwT6A" target="_blank" rel="noreferrer">UDCC</a></p>
                        </div>
                        <Searchbar searchText={searchText} updateSearchText={updateSearchText}/>

                        <h2>Filter by</h2>
                        <form>
                            {filterCategories}
                            <h2>Options</h2>
                            {otherCheckboxes}
                        </form>
                    </li>


                    <li id="sidebarbuttons"> 
                        <button onClick={resetCheckboxes}>Clear filter</button>
                        <button onClick={clearSelection}>Clear selection</button>
                        <div className="importexport">
                            <input id="fileUpload" type="file" onChange={handleFileUpload} hidden/>
                            <button className="importexportbutton" onClick={() => document.getElementById('fileUpload').click()}>Import</button>
                            <button className="importexportbutton" onClick={exportSelection}>Export</button>
                        </div>
                    </li>
                </ul>
            </div>
        );
    } else {
        return (
            <button onClick={() => setEnabled(true)} id="openbutton">{'>'}</button>
        );
    }
}

function slugify(input) {
    if (!input)
        return '';

    let slug = input.toLowerCase().trim();
    slug = slug.normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    slug = slug.replace(/[^a-z0-9\s-]/g, ' ').trim();
    slug = slug.replace(/[\s-]+/g, '_');

    return slug;
}